cd /tmp && cat > summ.py <<'EOF'
import json,glob,os,sys
res={}
for f in glob.glob('export/*.ndjson'):
    t=os.path.basename(f).split('.')[0]
    res[t]=[json.loads(l) for l in open(f)]
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            return e.get('valueString') or e.get('valueDateTime') or e.get('valueDate') or e.get('valueBoolean') or e.get('valueReference')
    return None
pats={p['id']:p for p in res['Patient']}
acc={}
for b in res['Basic']:
    acc[ext(b,'accession')]={'id':b['id'],'name':ext(b,'patient-name'),'mrn':ext(b,'patient-mrn'),'dob':ext(b,'patient-dob'),'recv':ext(b,'received')}
specs={s['id']:s for s in res['Specimen']}
def subj(r):
    for k in ('subject','patient','for'):
        if k in r: return r[k]['reference'].split('/')[-1]
    return None
order=[p['id'] for p in res['Patient']]
byp={p:[] for p in order}
for t,rs in res.items():
    if t in ('Patient','Basic'): continue
    for r in rs:
        s=subj(r)
        if s in byp: byp[s].append((ext(r,'event-time') or r.get('created') or '',t,r))
target=sys.argv[1] if len(sys.argv)>1 else None
for p in order:
    if target and p!=target: continue
    pt=pats[p]
    print('='*100)
    print(f"PATIENT {p} {pt['name'][0]['text']} MRN {pt['identifier'][0]['value']} DOB {pt['birthDate']} {pt['gender']}")
    for et,t,r in sorted(byp[p],key=lambda x:x[0]):
        if t=='EpisodeOfCare':
            print(f"  [EPISODE {r['id']}] dx_start={r['period']['start']} type={r['type'][0]['text']} status={r['status']}")
        elif t=='Condition':
            print(f"  {et} [Condition {r['id']}] {r['code']['text']} recorded={r.get('recordedDate')} recorder={r.get('recorder',{}).get('display')}")
        elif t=='Observation':
            sp=specs.get(r.get('specimen',{}).get('reference','').split('/')[-1])
            a=r.get('identifier',[{}])[0].get('value')
            ai=acc.get(a)
            line=f"  {et} [Obs {r['id']}] {r['code']['text']} coll={r.get('effectiveDateTime')} issued={r.get('issued')} status={r['status']} val={r.get('valueString')!r} acc={a}"
            print(line)
            if r.get('note'): print('        note:', ' | '.join(n['text'] for n in r['note']))
            if sp: print(f"        spec {sp['id']} coll={sp.get('collection',{}).get('collectedDateTime')} label={ext(sp,'label-name')}/{ext(sp,'label-mrn')}/{ext(sp,'label-dob')} accId={sp.get('accessionIdentifier',{}).get('value')} subj={subj(sp)}")
            if ai: print(f"        accession {ai['id']} {ai['name']}/{ai['mrn']}/{ai['dob']} recv={ai['recv']}")
        elif t=='MedicationAdministration':
            print(f"  {et} [MedAdmin {r['id']}] status={r['status']} eff={r.get('effectiveDateTime')} dose={r.get('dosage',{}).get('text')} perf={[x['actor']['display'] for x in r.get('performer',[])]}")
            if r.get('note'): print('        note:', ' | '.join(n['text'] for n in r['note']))
        elif t=='MedicationDispense':
            print(f"  {et} [MedDisp {r['id']}] qty={r.get('quantity')} daysSupply={r.get('daysSupply')} handed={r.get('whenHandedOver')} dosage={[d.get('text') for d in r.get('dosageInstruction',[])]}")
            if r.get('note'): print('        note:', ' | '.join(n['text'] for n in r['note']))
        elif t=='DocumentReference':
            print(f"  {et} [Doc {r['id']}] type={r.get('type',{}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={ext(r,'author-role')}")
