res={}
for f in glob.glob('export/*.ndjson'):
    t=os.path.basename(f).split('.')[0]
    res[t]=[json.loads(l) for l in open(f)]
def ext(r,name):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+name):
            return e.get('valueString') or e.get('valueDateTime') or e.get('valueDate') or e.get('valueBoolean') or e.get('valueReference')
    return None
pats={p['id']:p for p in res['Patient']}
acc={}
for b in res['Basic']:
    acc[ext(b,'accession')]={'id':b['id'],'name':ext(b,'patient-name'),'mrn':ext(b,'patient-mrn'),'dob':ext(b,'patient-dob'),'recv':ext(b,'received')}
specs={s['id']:s for s in res['Specimen']}
def subj(r):
    for k in ('subject','patient','for'):
        if k in r: return r[k]['reference'].split('/')[-1]
    return None
order=[p['id'] for p in res['Patient']]
byp={p:[] for p in order}
for t,rs in res.items():
    if t in ('Patient','Basic'): continue
    for r in rs:
        s=subj(r)
        if s in byp: byp[s].append((ext(r,'event-time') or r.get('created') or '',t,r))
target=sys.argv[1] if len(sys.argv)>1 else None
for p in order:
    if target and p!=target: continue
    pt=pats[p]
    print('='*100)
    print(f"PATIENT {p} {pt['name'][0]['text']} MRN {pt['identifier'][0]['value']} DOB {pt['birthDate']} {pt['gender']}")
    for et,t,r in sorted(byp[p],key=lambda x:x[0]):
        if t=='EpisodeOfCare':
