            print(line)
            if r.get('note'): print('        note:', ' | '.join(n['text'] for n in r['note']))
            if sp: print(f"        spec {sp['id']} coll={sp.get('collection',{}).get('collectedDateTime')} label={ext(sp,'label-name')}/{ext(sp,'label-mrn')}/{ext(sp,'label-dob')} accId={sp.get('accessionIdentifier',{}).get('value')} subj={subj(sp)}")
            if ai: print(f"        accession {ai['id']} {ai['name']}/{ai['mrn']}/{ai['dob']} recv={ai['recv']}")
        elif t=='MedicationAdministration':
            print(f"  {et} [MedAdmin {r['id']}] status={r['status']} eff={r.get('effectiveDateTime')} dose={r.get('dosage',{}).get('text')} perf={[x['actor']['display'] for x in r.get('performer',[])]}")
            if r.get('note'): print('        note:', ' | '.join(n['text'] for n in r['note']))
        elif t=='MedicationDispense':
            print(f"  {et} [MedDisp {r['id']}] qty={r.get('quantity')} daysSupply={r.get('daysSupply')} handed={r.get('whenHandedOver')} dosage={[d.get('text') for d in r.get('dosageInstruction',[])]}")
            if r.get('note'): print('        note:', ' | '.join(n['text'] for n in r['note']))
        elif t=='DocumentReference':
            print(f"  {et} [Doc {r['id']}] type={r.get('type',{}).get('text')} date={r.get('date')} author={[a.get('display') for a in r.get('author',[])]} role={ext(r,'author-role')}")
